@push('scripts')<script nonce="{{ $cspNonce }}">(()=>{const form=document.getElementById('audio-generation-form'),button=document.getElementById('audio-generation-button'),status=document.getElementById('audio-generation-status'),audio=document.getElementById('generated-audio');form.addEventListener('submit',async(event)=>{event.preventDefault();button.disabled=true;status.textContent='Generating securely…';audio.classList.add('d-none');try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json().catch(()=>({message:'The server returned an invalid response.'}));if(!response.ok||data.status!=='success')throw new Error(data.message||'Audio generation failed.');audio.src=String(data.audio_url);audio.classList.remove('d-none');status.textContent=String(data.message||'Audio saved.');}catch(error){status.textContent=error instanceof Error?error.message:'Audio generation failed.';}finally{button.disabled=false;}});})();</script>@endpush
